import React, { useState, useEffect } from 'react';
import axios from 'axios';
import './App.css';

function App() {
  const [amount, setAmount] = useState('');
  const [name, setName] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const [totalRaised, setTotalRaised] = useState(0);
  const [topDonors, setTopDonors] = useState([]);
  const [recentDonations, setRecentDonations] = useState([]);
  const [showUpiQr, setShowUpiQr] = useState(false);
  const [upiQrData, setUpiQrData] = useState(null);

  const goal = 450000;
  const API_URL = process.env.REACT_APP_API_URL || 'http://localhost:5000';

  const loadScript = (src) => {
    return new Promise((resolve) => {
      if (document.querySelector(`script[src="${src}"]`)) {
        resolve(true);
        return;
      }

      const script = document.createElement('script');
      script.src = src;
      script.onload = () => resolve(true);
      script.onerror = () => {
        console.error('Failed to load script:', src);
        resolve(false);
      };
      document.body.appendChild(script);
    });
  };

  const handlePayment = async (paymentMethod = 'razorpay') => {
    setLoading(true);
    setError(null);
    setShowUpiQr(false);

    if (amount === '' || parseInt(amount) < 1) {
      setError('Please enter an amount of at least ₹1');
      setLoading(false);
      return;
    }

    try {
      if (paymentMethod === 'upi_qr') {
        // For direct UPI QR without Razorpay
        const upiLink = `upi://pay?pa=your-merchant-vpa@upi&pn=GT+Bike+Fundraiser&am=${amount}&cu=INR&tn=Donation+for+GT+Bike`;
        setUpiQrData({
          link: upiLink,
          amount: amount
        });
        setShowUpiQr(true);
        setLoading(false);
        return;
      }

      // Razorpay payment flow
      const res = await loadScript('https://checkout.razorpay.com/v1/checkout.js');
      if (!res) {
        setError('Payment SDK failed to load');
        return;
      }

      const orderResponse = await axios.post(`${API_URL}/create-order`, {
        amount: parseInt(amount)
      });

      const { id: order_id, amount: order_amount } = orderResponse.data;

      const options = {
        key: process.env.REACT_APP_RAZORPAY_KEY_ID,
        amount: order_amount.toString(),
        currency: 'INR',
        name: 'GT Bike Fundraiser',
        description: 'Donation for GT Bike',
        order_id: order_id,
        handler: async function (response) {
          try {
            await axios.post(`${API_URL}/save-donation`, {
              name: name || 'Anonymous',
              amount: parseInt(amount),
              razorpay_payment_id: response.razorpay_payment_id,
              razorpay_order_id: response.razorpay_order_id,
              payment_method: 'razorpay'
            });
            fetchDonations();
            setAmount('');
            setName('');
          } catch (error) {
            console.error('Error saving donation:', error);
          }
        },
        theme: { color: '#FF6B00' },
        method: {
          netbanking: false,
          card: false,
          wallet: false,
          upi: true,  // Enable UPI
          paylater: false
        },
        notes: {
          purpose: 'GT Bike Donation'
        }
      };

      const rzp = new window.Razorpay(options);
      rzp.open();

      rzp.on('payment.method.upi.qr', function(response) {
        console.log('UPI QR generated:', response);
      });

    } catch (error) {
      console.error('Payment error:', error);
      setError(error.response?.data?.error || 'Error processing payment');
    } finally {
      setLoading(false);
    }
  };

  const fetchDonations = async () => {
    try {
      const response = await axios.get(`${API_URL}/get-donations`);
      setTotalRaised(response.data.total_raised || 0);
      setTopDonors(response.data.top_donors || []);
      setRecentDonations(response.data.recent_donations || []);
    } catch (error) {
      console.error('Error fetching donations:', error);
      setError('Failed to fetch donation data');
    }
  };

  useEffect(() => {
    fetchDonations();
  }, []);

  return (
    <div className="app">
      <div className="bike-background"></div>
      <div className="gradient-overlay"></div>

      <header className="header">
        <h1>Help Me Ride My Dream <span className="gt-text">GT650 Bike</span></h1>
        <p className="tagline">Every rupee brings me closer to the open road</p>
      </header>

      <main className="main-content">
        <div className="fundraiser-card">
          <div className="progress-container">
            <h3>Fundraising Progress</h3>
            <div className="progress-bar">
              <div
                className="progress-fill"
                style={{ width: `${Math.min(Math.round((totalRaised / goal) * 100), 100)}%` }}
              ></div>
            </div>
            <div className="progress-info">
              <span className="raised-amount">₹{totalRaised.toLocaleString()} raised</span>
              <span className="goal-amount">Goal: ₹{goal.toLocaleString()}</span>
            </div>
            <div className="progress-percent">{Math.round((totalRaised / goal) * 100)}% Complete</div>
          </div>

          <div className="donation-form">
            <h2>Fuel My Adventure</h2>
            <div className="form-group">
              <label htmlFor="name">Your Name (Optional)</label>
              <input
                id="name"
                type="text"
                value={name}
                onChange={(e) => setName(e.target.value)}
                placeholder="Enter your name"
              />
            </div>
            <div className="form-group">
              <label htmlFor="amount">Your Contribution (₹)</label>
              <input
                id="amount"
                type="number"
                min="1"
                value={amount}
                onChange={(e) => setAmount(e.target.value)}
                placeholder="Enter amount (min ₹1)"
              />
            </div>

            {error && <div className="error-message">{error}</div>}

            <button 
              onClick={() => handlePayment('razorpay')} 
              disabled={loading || amount === '' || parseInt(amount) < 1}
              className={`donate-button ${loading ? 'loading' : ''}`}
            >
              {loading ? 'Processing...' : 'Donate Now'}
            </button>

            <button 
              onClick={() => handlePayment('upi_qr')}
              disabled={loading || amount === '' || parseInt(amount) < 1}
              className="upi-qr-button"
            >
              Pay via UPI QR
            </button>
          </div>
        </div>

        {/* UPI QR Modal */}
        {showUpiQr && (
          <div className="upi-qr-modal">
            <div className="upi-qr-content">
              <h3>Scan to Pay via UPI</h3>
              <p>Amount: ₹{upiQrData.amount}</p>

              {/* QR Code would be generated here */}
              <div className="qr-code-placeholder">
                [UPI QR Code Would Appear Here]
                <p>Use any UPI app to scan this code</p>
              </div>

              <div className="upi-details">
                <p>Or send payment to:</p>
                <p className="upi-id">your-merchant-vpa@upi</p>
              </div>

              <button 
                onClick={() => setShowUpiQr(false)}
                className="close-qr-button"
              >
                Close
              </button>
            </div>
          </div>
        )}

        <div className="donors-grid">
          <div className="donors-card">
            <h3>🏆 Top Donors</h3>
            {topDonors.length > 0 ? (
              <ol className="donors-list">
                {topDonors.map((donor, index) => (
                  <li key={index}>
                    <span className="donor-name">{donor.name || 'Anonymous'}</span>
                    <span className="donor-amount">₹{donor.amount.toLocaleString()}</span>
                  </li>
                ))}
              </ol>
            ) : (
              <p className="no-donations">No donors yet</p>
            )}
          </div>

          <div className="donors-card">
            <h3>🆕 Recent Donations</h3>
            {recentDonations.length > 0 ? (
              <ul className="donors-list">
                {recentDonations.map((donation, index) => (
                  <li key={index}>
                    <span className="donor-name">{donation.name || 'Anonymous'}</span>
                    <span className="donor-amount">₹{donation.amount.toLocaleString()}</span>
                  </li>
                ))}
              </ul>
            ) : (
              <p className="no-donations">No recent donations</p>
            )}
          </div>
        </div>
      </main>

      <footer className="footer">
        <p>Thank you for supporting my passion!</p>
      </footer>
    </div>
  );
}

export default App;
